import{_ as a,o as r,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Multi-ledger","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/04-multi-ledger-guide.md","filePath":"v1/en/guide/04-multi-ledger-guide.md"}'),i={name:"v1/en/guide/04-multi-ledger-guide.md"};function n(o,e,d,s,c,g){return r(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="multi-ledger" tabindex="-1">Multi-ledger <a class="header-anchor" href="#multi-ledger" aria-label="Permalink to &quot;Multi-ledger&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>Expense Tracker: Koala (“Koala”) supports multiple ledgers so you can manage different budgets separately. Each ledger has its own name, currency, categories, and statistics.</p><p>Common scenarios:</p><ul><li>Personal</li><li>Family</li><li>Travel</li><li>Baby</li><li>Car</li><li>Home renovation</li><li>Business</li></ul><hr><h2 id="🚀-quick-start" tabindex="-1">🚀 Quick Start <a class="header-anchor" href="#🚀-quick-start" aria-label="Permalink to &quot;🚀 Quick Start&quot;">​</a></h2><h3 id="create-a-new-ledger" tabindex="-1">Create a new ledger <a class="header-anchor" href="#create-a-new-ledger" aria-label="Permalink to &quot;Create a new ledger&quot;">​</a></h3><ol><li>Open Expense Tracker: Koala</li><li>Tap <strong>Settings</strong></li><li>Tap <strong>Ledger management</strong></li><li>Tap <strong>+</strong></li><li>Fill in ledger info (name/description/icon/currency)</li><li>Tap <strong>Save</strong></li></ol><h3 id="switch-ledgers" tabindex="-1">Switch ledgers <a class="header-anchor" href="#switch-ledgers" aria-label="Permalink to &quot;Switch ledgers&quot;">​</a></h3><ol><li>Open <strong>Ledger management</strong></li><li>Tap a ledger card to switch</li></ol><blockquote><p>📝 Note: After switching, overview/statistics/bill list will show data for the current ledger.</p></blockquote><hr><h2 id="📚-ledger-management" tabindex="-1">📚 Ledger management <a class="header-anchor" href="#📚-ledger-management" aria-label="Permalink to &quot;📚 Ledger management&quot;">​</a></h2><h3 id="edit-a-ledger" tabindex="-1">Edit a ledger <a class="header-anchor" href="#edit-a-ledger" aria-label="Permalink to &quot;Edit a ledger&quot;">​</a></h3><ol><li>Open <strong>Ledger management</strong></li><li>Tap the <strong>More</strong> button on the ledger card</li><li>Edit name/description/icon/currency</li><li>Tap <strong>Save</strong></li></ol><h3 id="delete-a-ledger" tabindex="-1">Delete a ledger <a class="header-anchor" href="#delete-a-ledger" aria-label="Permalink to &quot;Delete a ledger&quot;">​</a></h3><ol><li>Open ledger details</li><li>Tap <strong>Delete ledger</strong></li><li>Confirm</li></ol><blockquote><p>⚠️ Warning:</p><ul><li>Deleting a ledger removes the ledger and its bills.</li><li>The ledger is removed from this device; if cloud sync is enabled, it will also be removed from the cloud after the next sync.</li><li>This action cannot be restored inside the app.</li></ul></blockquote><hr><h2 id="🔧-faq" tabindex="-1">🔧 FAQ <a class="header-anchor" href="#🔧-faq" aria-label="Permalink to &quot;🔧 FAQ&quot;">​</a></h2><h3 id="how-many-ledgers-can-i-create" tabindex="-1">How many ledgers can I create? <a class="header-anchor" href="#how-many-ledgers-can-i-create" aria-label="Permalink to &quot;How many ledgers can I create?&quot;">​</a></h3><p>You can create up to <strong>50</strong> ledgers.</p><h3 id="are-accounts-ledger-based" tabindex="-1">Are accounts ledger-based? <a class="header-anchor" href="#are-accounts-ledger-based" aria-label="Permalink to &quot;Are accounts ledger-based?&quot;">​</a></h3><p>No. Accounts are device-based and shared across all ledgers.</p><hr><p><strong>Last updated</strong>: Jan 2026</p>',27)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
